# -*- coding: utf-8 -*-
DEEPA = {
"IAS 19": [
("أنواع منافع الموظفين", [
"يغطي المعيار أربع فئات: المنافع قصيرة الأجل (رواتب وإجازات سنوية ومكافآت تُسوّى خلال 12 شهرًا بعد نهاية الفترة)، ومنافع ما بعد انتهاء الخدمة (معاشات ومكافأة نهاية الخدمة)، ومنافع الأجل الطويل الأخرى (إجازات طويلة وجوائز الخدمة الطويلة)، ومنافع إنهاء الخدمة.",
"تُسجَّل المنافع قصيرة الأجل مصروفًا في الفترة التي قدّم فيها الموظف الخدمة، وتُسجَّل الالتزامات غير المدفوعة بالمبلغ غير المخصوم. أما الإجازات المتراكمة غير المستخدمة فتُحتسب التزامًا بالتكلفة المتوقعة التي ستدفعها المنشأة مقابل الاستحقاق غير المستخدم."]),
("خطط الاشتراكات المحددة والمنافع المحددة", [
"في خطة الاشتراكات المحددة (مثل التأمينات الاجتماعية) يقتصر التزام المنشأة على الاشتراك المتفق عليه، فيُسجَّل المصروف عند استحقاق الاشتراك ولا تنشأ مخاطر اكتوارية عليها.",
"في خطة المنافع المحددة تتحمل المنشأة المخاطر، ويُعدّ التزام مكافأة نهاية الخدمة وفق نظام العمل السعودي عادةً خطة منافع محددة. يُقاس الالتزام بالقيمة الحالية للمنافع المستحقة باستخدام طريقة وحدة الائتمان المتوقعة وافتراضات اكتوارية: معدل الخصم (عائد سندات شركات عالية الجودة أو سندات حكومية)، والزيادات المتوقعة في الرواتب، ومعدلات دوران الموظفين ووفياتهم.",
"المبلغ المعترف به في قائمة المركز المالي = القيمة الحالية للالتزام - القيمة العادلة لأصول الخطة (إن وُجدت)، مع مراعاة سقف الأصل."]),
("مكونات التكلفة وإعادة القياس", [
"تُسجَّل في الربح أو الخسارة: تكلفة الخدمة الحالية وتكلفة الخدمة السابقة وأرباح أو خسائر التسوية، وصافي الفائدة على صافي الالتزام. أما إعادة القياس، وتشمل الأرباح والخسائر الاكتوارية، فتُسجَّل فورًا في الدخل الشامل الآخر ولا تُعاد لاحقًا إلى الربح أو الخسارة.",
"مثال: تكلفة الخدمة الحالية لمكافأة نهاية الخدمة 120,000 وصافي الفائدة 18,000 وخسارة اكتوارية 30,000.",
"قيد: من حـ/ مصروف منافع الموظفين 138,000 ومن حـ/ الدخل الشامل الآخر (خسارة اكتوارية) 30,000 — إلى حـ/ التزام منافع نهاية الخدمة 168,000."]),
("منافع إنهاء الخدمة والإفصاح", [
"تُسجَّل منافع إنهاء الخدمة في وقت مبكر من التاريخين: عندما لا تستطيع المنشأة سحب العرض، أو عندما تعترف بتكاليف إعادة هيكلة تدخل في نطاق IAS 37 وتتضمن دفع منافع إنهاء.",
"من أهم الإفصاحات: وصف الخطة والمخاطر المرتبطة بها، ومطابقة الرصيد الافتتاحي والختامي للالتزام، والافتراضات الاكتوارية الرئيسية، وتحليل الحساسية لتغير معدل الخصم وزيادة الرواتب. نصيحة: استعن باكتواري مؤهل سنويًا، ولا تكتفِ بالحساب النظامي المبسّط لأنه قد يختلف جوهريًا عن القياس وفق IAS 19."]),
],
"IAS 23": [
("نطاق المعيار والأصل المؤهل", [
"تُرسمل تكاليف الاقتراض المنسوبة مباشرة إلى اقتناء أو إنشاء أو إنتاج أصل مؤهل كجزء من تكلفته. والأصل المؤهل هو أصل يحتاج بالضرورة إلى فترة زمنية طويلة ليصبح جاهزًا للاستخدام أو البيع، مثل المباني الكبيرة والمصانع ومحطات الطاقة وبعض المخزون طويل التصنيع.",
"تشمل تكاليف الاقتراض الفائدة المحسوبة بطريقة الفائدة الفعلية والرسوم وأعباء التمويل الأخرى وفروق الصرف المتعلقة بالاقتراض بالعملة الأجنبية بقدر ما تُعدّ تعديلًا لتكلفة الفائدة. والأصول المقاسة بالقيمة العادلة والمخزون المنتَج بكميات كبيرة وبصورة متكررة غير مشمولة."]),
("بدء الرسملة وتعليقها وإيقافها", [
"تبدأ الرسملة عندما تتحقق ثلاثة شروط معًا: تكبّد نفقات على الأصل، وتكبّد تكاليف اقتراض، وبدء الأنشطة اللازمة لإعداد الأصل للاستخدام المقصود.",
"تُعلَّق الرسملة خلال فترات طويلة تتوقف فيها الأنشطة التطويرية النشطة، ولا تُعلَّق عند فترات تأخير مؤقتة أو ضرورية فنيًا. وتتوقف الرسملة عندما تكتمل جوهريًا كل الأنشطة اللازمة لإعداد الأصل، حتى لو لم يبدأ استخدامه فعليًا."]),
("القروض المخصصة والعامة", [
"في الاقتراض المخصص لأصل معين تُرسمل تكاليف الاقتراض الفعلية المتكبدة خلال الفترة، مخصومًا منها أي دخل استثمار ناتج عن الاستثمار المؤقت لجزء القرض غير المنفق بعد.",
"في الاقتراض العام تُحسب التكاليف القابلة للرسملة بتطبيق معدل رسملة على متوسط النفقات على الأصل خلال الفترة. ومعدل الرسملة هو المتوسط المرجّح لتكاليف الاقتراض على القروض القائمة غير المخصصة. ولا يتجاوز المبلغ المرسمل إجمالي تكاليف الاقتراض المتكبدة فعلًا.",
"مثال: أنفقت شركة على إنشاء مصنع متوسط 4,000,000 خلال السنة، ومعدل الرسملة 7%. المبلغ المرسمل = 4,000,000 × 7% = 280,000.",
"قيد: من حـ/ مباني تحت الإنشاء (مصنع) 280,000 — إلى حـ/ مصروف فوائد 280,000."]),
("نقاط تطبيقية", [
"إذا زادت القيمة الدفترية للأصل بعد الرسملة على المبلغ القابل للاسترداد يُسجَّل انخفاض القيمة وفق IAS 36. ويُفصح عن مبلغ تكاليف الاقتراض المرسملة ومعدل الرسملة المستخدم.",
"من الأخطاء الشائعة: رسملة الفوائد بعد اكتمال الأصل، أو رسملة فوائد على أصول لا تحتاج فترة طويلة، أو إغفال دخل الاستثمار المؤقت على القروض المخصصة."]),
],
"IAS 24": [
("من هم الأطراف ذوو العلاقة؟", [
"الطرف ذو العلاقة شخص أو منشأة مرتبطة بالمنشأة التي تعدّ القوائم. من الأشخاص: من يسيطر أو يمارس تأثيرًا مهمًا أو سيطرة مشتركة على المنشأة، وأفراد الإدارة العليا، وأفراد العائلة المقربون منهم. ومن المنشآت: الشركة الأم والتابعة والزميلة والمشروع المشترك والشركات تحت سيطرة مشتركة وخطط منافع ما بعد التوظيف لموظفي المنشأة.",
"المنشآت التي يشترك في إدارتها العليا شخص واحد ليست بالضرورة ذات علاقة ببعضها، لكن يجب التحقق من جوهر العلاقة وليس شكلها القانوني فقط."]),
("المعاملات المشمولة والإفصاح", [
"المعاملة هي تحويل موارد أو خدمات أو التزامات بين أطراف ذات علاقة، سواء بمقابل أو دونه. وتشمل البيع والشراء والإيجارات والقروض والضمانات والتعويضات وتقديم الخدمات والتحويلات بموجب اتفاقيات ترخيص أو تمويل.",
"تُفصح المنشأة عن طبيعة العلاقة، وحجم المعاملات والأرصدة القائمة بما فيها التعهدات، والشروط والأحكام، وأي مخصصات ديون مشكوك فيها، والمصروف المعترف به عن الديون المعدومة على أطراف ذات علاقة. ويجب الإفصاح عن علاقة المنشأة بالشركة الأم والجهة المسيطرة النهائية حتى لو لم تحدث معاملات."]),
("تعويضات كبار الإداريين", [
"يُفصح عن إجمالي تعويضات الإدارة العليا وعن كل فئة منها: منافع قصيرة الأجل، ومنافع ما بعد انتهاء الخدمة، ومنافع الأجل الطويل الأخرى، ومنافع إنهاء الخدمة، والدفع على أساس الأسهم.",
"أفراد الإدارة العليا هم من لديهم السلطة والمسؤولية عن التخطيط والتوجيه والرقابة على أنشطة المنشأة، ويشمل ذلك أعضاء مجلس الإدارة التنفيذيين وغير التنفيذيين."]),
("إعفاء المنشآت الحكومية وملاحظات", [
"تُعفى المنشأة المرتبطة بحكومة من بعض متطلبات الإفصاح عن المعاملات مع الحكومة أو مع منشآت أخرى مرتبطة بالحكومة نفسها، لكن يجب الإفصاح عن طبيعة وحجم المعاملات المهمة منفردة أو مجتمعة.",
"لا يجوز الادعاء بأن شروط معاملة مع طرف ذي علاقة مماثلة لمعاملات مستقلة إلا إذا كان بالإمكان إثبات ذلك. نصيحة: احتفظ بسجل محدّث للأطراف ذوي العلاقة يُراجع ربع سنويًا، واطلب إقرارات سنوية من أعضاء مجلس الإدارة والإدارة العليا."]),
],
"IAS 33": [
("ربحية السهم الأساسية", [
"تُحسب ربحية السهم الأساسية بقسمة الربح أو الخسارة العائد إلى حملة الأسهم العادية للمنشأة الأم (بعد خصم توزيعات الأسهم الممتازة) على المتوسط المرجّح لعدد الأسهم العادية القائمة خلال الفترة. وتنطبق على المنشآت التي تتداول أسهمها العادية علنًا أو التي تقدّم أوراقها المالية لجهة تنظيمية.",
"يُوزن عدد الأسهم المصدرة خلال الفترة بحسب الجزء الزمني الذي كانت فيه قائمة. مثال: 1,000,000 سهم في بداية السنة، وأُصدر 300,000 سهم في 1 أبريل. المتوسط المرجّح = 1,000,000 + 300,000 × 9/12 = 1,225,000 سهم. إذا كان الربح العائد للمساهمين العاديين 980,000 فإن ربحية السهم = 0.80."]),
("أسهم المنحة والتجزئة", [
"أسهم المنحة وتجزئة الأسهم لا تغيّر الموارد، لذلك تُعدَّل أعداد الأسهم بأثر رجعي كأنها وُجدت من بداية أقدم فترة معروضة، وتُعاد صياغة ربحية السهم للفترات المقارنة.",
"أما الإصدار بسعر السوق مقابل نقد فيُوزَن من تاريخ استلام المقابل، وإصدار حقوق الأولوية بسعر أقل من السوق يتضمن عنصر منحة يُعدَّل بعامل مناسب."]),
("ربحية السهم المخفّضة", [
"تُعدَّل ربحية السهم المخفّضة بافتراض تحويل جميع الأسهم العادية المحتملة المخفِّضة، مثل السندات القابلة للتحويل وخيارات الأسهم والمنح. في السندات القابلة للتحويل يُضاف إلى البسط الفائدة بعد الضريبة التي كانت ستُوفَّر، ويُضاف إلى المقام الأسهم المتحصلة عند التحويل.",
"للخيارات والمنح تُطبَّق طريقة الأسهم الخزينة: يُفترض أن المتحصلات من الممارسة تُستخدم لشراء أسهم بالسعر المتوسط للسوق، والفرق في عدد الأسهم يُضاف للمقام. والأسهم المحتملة لا تُعدّ مخفِّضة إلا إذا خفّضت الربحية من العمليات المستمرة."]),
("العرض والإفصاح", [
"تُعرض ربحية السهم الأساسية والمخفّضة في قائمة الربح أو الخسارة لكل فئة من الأسهم العادية، وللعمليات المستمرة وللربح الكلي، ويُعرض مثيلها للعمليات المتوقفة في القائمة أو الإيضاحات.",
"يُفصح عن مطابقة البسط والمقام للربحية الأساسية والمخفّضة، وعن الأدوات التي لم تدخل الحساب لأنها مانعة للتخفيض. ويعرضها حتى لو كانت الخسارة. نصيحة: أنشئ جدولًا شهريًا بتواريخ إصدار الأسهم لتسهيل حساب المتوسط المرجّح وتجنب الخطأ في التواريخ."]),
],
"IFRS 5": [
("شروط التصنيف كمحتفظ بها للبيع", [
"يُصنّف الأصل غير المتداول (أو مجموعة الاستبعاد) محتفظًا به للبيع إذا كان سيُسترد قيمته الدفترية بصورة رئيسية عبر معاملة بيع لا عبر الاستخدام المستمر. ويشترط أن يكون الأصل متاحًا للبيع الفوري بحالته الراهنة وفق شروط معتادة، وأن يكون البيع محتمل الحدوث بدرجة كبيرة.",
"يستلزم احتمال البيع التزام الإدارة بخطة بيع، وبدء برنامج نشط للعثور على مشترٍ، وعرض الأصل بسعر معقول مقارنة بقيمته العادلة، وأن يُتوقع إتمام البيع خلال سنة من التصنيف مع استثناءات محدودة للتأخيرات خارج سيطرة المنشأة."]),
("القياس والإهلاك", [
"يُقاس الأصل المحتفظ به للبيع بالأقل من قيمته الدفترية وقيمته العادلة ناقصًا تكاليف البيع. ويُسجَّل أي انخفاض في الربح أو الخسارة، ولا يُحتسب إهلاك أو إطفاء للأصل بعد التصنيف.",
"مثال: آلة قيمتها الدفترية 500,000 وقيمتها العادلة 450,000 وتكاليف البيع 10,000. تُقاس بـ 440,000 فتُسجَّل خسارة 60,000.",
"قيد: من حـ/ خسارة انخفاض أصول محتفظ بها للبيع 60,000 — إلى حـ/ أصول محتفظ بها للبيع 60,000 (بعد إعادة تبويب الأصل من الأصول الثابتة)."]),
("العمليات المتوقفة", [
"العملية المتوقفة جزء من المنشأة تم استبعاده أو تصنيفه محتفظًا به للبيع، ويمثل خط أعمال رئيسيًا أو منطقة جغرافية رئيسية، أو جزءًا من خطة منسّقة لاستبعاد خط أعمال رئيسي، أو شركة تابعة اقتُنيت حصريًا بغرض إعادة البيع.",
"يُعرض مبلغ واحد في قائمة الربح أو الخسارة يشمل ربح أو خسارة العمليات المتوقفة بعد الضريبة وربح أو خسارة القياس والاستبعاد. ويُعاد عرض أرقام المقارنة لتظهر العملية كمتوقفة."]),
("العرض والإفصاح", [
"تُعرض الأصول والالتزامات المحتفظ بها للبيع بصورة منفصلة في قائمة المركز المالي دون مقاصة بين الأصول والالتزامات، ولا تُعاد صياغة أرقام المقارنة في الميزانية.",
"يُفصح عن وصف الأصل وظروف البيع وطريقة التخلص المتوقعة وتوقيته والقطاع المرتبط به. وإذا لم تعد معايير التصنيف قائمة يُعاد قياس الأصل بالأقل من قيمته الدفترية قبل التصنيف (معدّلة بالإهلاك الذي كان سيُحتسب) ومبلغه القابل للاسترداد."]),
],
"IFRS 10": [
("تعريف السيطرة", [
"يعتمد التوحيد على مفهوم السيطرة: تسيطر المنشأة على منشأة مستثمَر فيها إذا كانت معرّضة للعوائد المتغيرة أو لها حقوق فيها نتيجة مشاركتها، ولديها القدرة على التأثير في تلك العوائد من خلال سلطتها على المنشأة. أي يلزم توفر ثلاثة عناصر معًا: السلطة، والتعرض للعوائد المتغيرة، وصلة بينهما.",
"السلطة هي حقوق قائمة تعطي القدرة الحالية على توجيه الأنشطة ذات الصلة التي تؤثر جوهريًا في العوائد، مثل تحديد السياسات التشغيلية والمالية أو تعيين الإدارة العليا. وقد تنشأ السلطة من حقوق التصويت أو من اتفاقيات تعاقدية، وتُقيَّم عند تغير الحقائق والظروف."]),
("إجراءات التوحيد", [
"تُجمع بنود الأصول والالتزامات وحقوق الملكية والإيرادات والمصروفات والتدفقات للشركة الأم مع التابعة بندًا ببند، ثم تُستبعد القيمة الدفترية لاستثمار الأم في كل تابعة وحصتها في حقوق الملكية فيها، وتُحذف بالكامل الأرصدة والمعاملات والأرباح والخسائر غير المحققة بين منشآت المجموعة.",
"يجب استخدام سياسات محاسبية موحدة وقوائم بالتاريخ نفسه، وإذا اختلفت التواريخ فلا تتجاوز الفجوة ثلاثة أشهر مع تعديلات للأحداث المهمة."]),
("الحصة غير المسيطرة وفقدان السيطرة", [
"تُعرض الحصة غير المسيطرة ضمن حقوق الملكية بصورة منفصلة عن حقوق ملاك الأم، ويُوزَّع الدخل الشامل بين الأم والحصة غير المسيطرة حتى لو أدى ذلك إلى رصيد عجز.",
"التغير في حصة الملكية دون فقدان السيطرة معاملة بين مالكي حقوق الملكية، فلا يُسجَّل ربح أو خسارة ولا تُعدَّل الشهرة، بل يُعدَّل الفرق في حقوق ملكية الأم. أما عند فقدان السيطرة فتُستبعد أصول وخصوم التابعة والحصة غير المسيطرة، وتُعترف بأي استثمار محتفظ به بقيمته العادلة، ويُسجَّل الربح أو الخسارة في الربح أو الخسارة.",
"قيد توضيحي: عند بيع 10% من تابعة مع بقاء السيطرة مقابل 200,000 والحصة غير المسيطرة المضافة 150,000: من حـ/ النقدية 200,000 — إلى حـ/ الحصة غير المسيطرة 150,000 وإلى حـ/ حقوق ملكية الأم 50,000."]),
("منشآت الاستثمار والحالات الخاصة", [
"منشأة الاستثمار لا توحّد تابعاتها، بل تقيس استثماراتها بالقيمة العادلة من خلال الربح أو الخسارة، وتتحقق فيها شروط: الحصول على أموال من مستثمرين لتقديم خدمات إدارة استثمارات، والتعهد بأن غرضها استثمار الأموال لعوائد رأس المال أو الدخل أو كليهما، وتقييم أداء استثماراتها على أساس القيمة العادلة.",
"من الحالات الدقيقة: الوكيل مقابل الأصيل (هل يتصرف المدير لمصلحة الآخرين أم لنفسه)، والمنشآت المهيكلة التي لا تكون حقوق التصويت فيها العامل الحاسم، وحقوق الحماية التي لا تمنح سلطة. نصيحة: وثّق تحليل السيطرة لكل استثمار جوهري سنويًا ويُحدَّث عند تغير الحقائق."]),
],
}
